//! Table-definition bytes (card C-T6a2): the §3 def format with the
//! §3.1 pinned type tags — the golden def corpus
//! (`tests/golden_row/defs.tsv`, hex regenerated by `row_gen`), the
//! totality of `TableSchema::decode` (every malformed def is an `Err`),
//! the `InvalidDdl` refusals of `TableSchema::new` / `encode`, and a
//! round-trip proptest.

mod reference;

use nucleus_codec::row::{value_repr_eq, ColumnDef, RowError, TableSchema};
use nucleus_codec::{Collation, KeyType, Value};
use proptest::collection::vec;
use proptest::prelude::*;
use reference::{key_type, optional_value};
use std::collections::BTreeMap;
use std::path::PathBuf;

fn cfg() -> ProptestConfig {
    let cases = std::env::var("NUCLEUS_CODEC_CASES")
        .ok()
        .map(|s| {
            s.parse::<u32>()
                .unwrap_or_else(|e| panic!("bad NUCLEUS_CODEC_CASES {s:?}: {e}"))
        })
        .unwrap_or(10_000);
    let mut config = ProptestConfig::with_cases(cases);
    // The golden corpus pins the bytes; failing seeds would add files
    // without adding information.
    config.failure_persistence = None;
    config
}

fn cd(attnum: u16, name: &str, ty: KeyType) -> ColumnDef {
    ColumnDef {
        attnum,
        name: name.to_string(),
        ty,
        not_null: false,
        not_null_since: 0,
        dropped: false,
        missing: None,
    }
}

fn sch(columns: Vec<ColumnDef>, pk: Vec<u16>) -> TableSchema {
    TableSchema::new(columns, pk).unwrap_or_else(|e| panic!("case schema: {e:?}"))
}

/// The golden def cases: (name, description, schema). Mirrored by
/// `row_gen.rs`; the pinned hex makes the two tables fail loudly if
/// they drift apart.
fn def_cases() -> Vec<(&'static str, &'static str, TableSchema)> {
    let one = |ty: KeyType| sch(vec![cd(1, "c", ty)], vec![1]);
    let mut flagged = cd(1, "c", KeyType::Int4);
    flagged.not_null = true;
    let mut dropped = cd(1, "c", KeyType::Int4);
    // The DDL-producible state (drop_column clears not_null, §3). A
    // hand-built not_null is canonicalized away by encode — pinned by
    // encode_canonicalizes_dropped_not_null below (gate follow-up f2).
    dropped.dropped = true;
    let mut missing = cd(1, "c", KeyType::Int4);
    missing.missing = Some(Value::Int4(7));
    let mut missing_text = cd(1, "c", KeyType::Text(Collation::C));
    missing_text.missing = Some(Value::Text("héllo".to_string()));
    vec![
        ("bool", "one bool column, pk (tag 01)", one(KeyType::Bool)),
        ("int2", "tag 02", one(KeyType::Int2)),
        ("int4", "tag 03", one(KeyType::Int4)),
        ("int8", "tag 04", one(KeyType::Int8)),
        ("float4", "tag 05", one(KeyType::Float4)),
        ("float8", "tag 06", one(KeyType::Float8)),
        ("numeric", "tag 07", one(KeyType::Numeric)),
        (
            "text",
            "tag 08 + collation byte 01",
            one(KeyType::Text(Collation::C)),
        ),
        ("bytea", "tag 09", one(KeyType::Bytea)),
        ("date", "tag 0a", one(KeyType::Date)),
        ("time", "tag 0b", one(KeyType::Time)),
        ("timestamp", "tag 0c", one(KeyType::Timestamp)),
        ("timestamptz", "tag 0d", one(KeyType::TimestampTz)),
        ("interval", "tag 0e", one(KeyType::Interval)),
        ("uuid", "tag 0f", one(KeyType::Uuid)),
        ("jsonb", "tag 10", one(KeyType::Jsonb)),
        (
            "array_int4",
            "tag 11 + element tag 03",
            one(KeyType::Array(Box::new(KeyType::Int4))),
        ),
        (
            "array_text",
            "tag 11 + element 08 01",
            one(KeyType::Array(Box::new(KeyType::Text(Collation::C)))),
        ),
        ("not_null", "flags bit0", sch(vec![flagged], vec![1])),
        (
            "dropped",
            "flags bit1 only (drop clears not_null), no pk",
            sch(vec![dropped], vec![]),
        ),
        (
            "missing_int4",
            "flags bit2 + be32 len + int4 value bytes",
            sch(vec![missing], vec![1]),
        ),
        (
            "missing_text",
            "a text default (UTF-8 value bytes)",
            sch(vec![missing_text], vec![1]),
        ),
        (
            "two_pk",
            "(a int8, b text), pk [1, 2]",
            sch(
                vec![
                    cd(1, "a", KeyType::Int8),
                    cd(2, "b", KeyType::Text(Collation::C)),
                ],
                vec![1, 2],
            ),
        ),
        (
            "hidden_rowid",
            "no pk: hidden_rowid byte 1, npk 0",
            sch(vec![cd(1, "a", KeyType::Int4)], vec![]),
        ),
        (
            "long_name",
            "a name longer than one byte",
            sch(vec![cd(1, "renamed_by_ddl_column", KeyType::Int4)], vec![1]),
        ),
        ("empty", "no columns at all, no pk", sch(vec![], vec![])),
    ]
}

struct DefLine {
    name: String,
    hex: Vec<u8>,
}

fn load_defs() -> Vec<DefLine> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden_row/defs.tsv");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    text.lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|line| {
            let mut f = line.split('\t');
            let name = f
                .next()
                .unwrap_or_else(|| panic!("{line}: name"))
                .to_string();
            let hex = f
                .nth(1)
                .unwrap_or_else(|| panic!("{line}: hex (run row_gen)"));
            let bytes = (0..hex.len())
                .step_by(2)
                .map(|i| {
                    u8::from_str_radix(&hex[i..i + 2], 16).unwrap_or_else(|e| panic!("{line}: {e}"))
                })
                .collect();
            DefLine { name, hex: bytes }
        })
        .collect()
}

/// One pinned hex per §3.1 tag (plus the flag, pk and hidden-rowid
/// shapes): the bytes `TableSchema::encode` produces must equal the
/// file, and the file must decode back to the same schema. Any change
/// to the tag table or the def layout fails here.
#[test]
fn def_golden() {
    let lines = load_defs();
    assert!(!lines.is_empty(), "no defs in the corpus");
    let cases = def_cases();
    let by_name: BTreeMap<&str, &TableSchema> = cases
        .iter()
        .map(|(name, _, schema)| (*name, schema))
        .collect();
    let names: Vec<&str> = lines.iter().map(|l| l.name.as_str()).collect();
    let want: Vec<&str> = cases.iter().map(|(name, _, _)| *name).collect();
    assert_eq!(
        want, names,
        "the corpus must cover exactly the def cases (in order)"
    );
    for line in &lines {
        let schema = by_name
            .get(line.name.as_str())
            .copied()
            .unwrap_or_else(|| panic!("unknown case {}", line.name));
        let bytes = schema
            .encode()
            .unwrap_or_else(|e| panic!("{}: encode: {e}", line.name));
        assert_eq!(
            line.hex, bytes,
            "{}: def bytes drifted (row_gen rewrites only the hex column)",
            line.name
        );
        assert_eq!(
            Ok(schema.clone()),
            TableSchema::decode(&line.hex),
            "{}: does not decode back",
            line.name
        );
        assert_eq!(
            schema.hidden_rowid,
            schema.pk.is_empty(),
            "{}: hidden_rowid invariant",
            line.name
        );
    }
}

/// Truncation at every offset of every golden def is an error, never a
/// panic.
#[test]
fn def_truncation_at_every_offset() {
    for line in load_defs() {
        for cut in 0..line.hex.len() {
            assert!(
                TableSchema::decode(&line.hex[..cut]).is_err(),
                "{}: accepted cut {cut} of {:02x?}",
                line.name,
                line.hex
            );
        }
    }
}

/// Gate follow-up f2: `encode` canonicalizes the dropped state — a
/// hand-built `dropped` + `not_null` column, impossible via DDL (DROP
/// COLUMN clears `not_null`, §3), encodes with flags bit1 only, and
/// bit0 does not survive the round trip.
#[test]
fn encode_canonicalizes_dropped_not_null() {
    let mut hand = cd(1, "c", KeyType::Int4);
    hand.dropped = true;
    hand.not_null = true;
    let bytes = sch(vec![hand], vec![])
        .encode()
        .unwrap_or_else(|e| panic!("encode: {e:?}"));
    // 5401 | 00000001 | 01 | 0001 | 0001 | 00000001 | 63 'c' | 03 tag |
    // flags | 0000 npk: the flags byte is byte 17.
    assert_eq!(0x02, bytes[17], "a dropped column must show bit1 only");
    let back = TableSchema::decode(&bytes).unwrap_or_else(|e| panic!("decode: {e:?}"));
    assert!(back.columns[0].dropped);
    assert!(!back.columns[0].not_null);
}

/// Hand-assembled §3 bytes, so the corrupt cases do not depend on the
/// encoder. Each column is (attnum, name, tail) where the tail is the
/// type bytes plus flags (and the missing value when bit2 is set).
fn raw_def(version: u32, hidden: u8, cols: &[(u16, &str, &[u8])], pk: &[u16]) -> Vec<u8> {
    let mut out = vec![0x54, 0x01];
    out.extend_from_slice(&version.to_be_bytes());
    out.push(hidden);
    out.extend_from_slice(&(cols.len() as u16).to_be_bytes());
    for (attnum, name, tail) in cols {
        out.extend_from_slice(&attnum.to_be_bytes());
        out.extend_from_slice(&(name.len() as u32).to_be_bytes());
        out.extend_from_slice(name.as_bytes());
        out.extend_from_slice(tail);
    }
    out.extend_from_slice(&(pk.len() as u16).to_be_bytes());
    for &a in pk {
        out.extend_from_slice(&a.to_be_bytes());
    }
    out
}

const INT8_TAIL: &[u8] = &[0x04, 0x00];

/// Decode is total (§3): every malformed def is `Err(RowError::Corrupt)`.
#[test]
fn def_decode_rejects() {
    let good = raw_def(1, 0, &[(1, "a", INT8_TAIL)], &[1]);
    assert_eq!(Ok(()), TableSchema::decode(&good).map(|_| ()));

    let mut bad_magic = good.clone();
    bad_magic[0] = 0x55;
    assert_eq!(
        Err(RowError::Corrupt("definition magic")),
        TableSchema::decode(&bad_magic)
    );

    // §3: version is 1 at CREATE TABLE, +1 per DDL — 0 is unproducible.
    assert_eq!(
        Err(RowError::Corrupt("definition version 0")),
        TableSchema::decode(&raw_def(0, 0, &[(1, "a", INT8_TAIL)], &[1]))
    );

    // hidden_rowid byte: only 0/1, and it must equal npk == 0.
    assert_eq!(
        Err(RowError::Corrupt("hidden_rowid byte")),
        TableSchema::decode(&raw_def(1, 2, &[(1, "a", INT8_TAIL)], &[1]))
    );
    assert_eq!(
        Err(RowError::Corrupt("hidden_rowid byte")),
        TableSchema::decode(&raw_def(1, 0xFF, &[(1, "a", INT8_TAIL)], &[]))
    );
    assert_eq!(
        Err(RowError::Corrupt("hidden_rowid disagrees with npk")),
        TableSchema::decode(&raw_def(1, 1, &[(1, "a", INT8_TAIL)], &[1]))
    );
    assert_eq!(
        Err(RowError::Corrupt("hidden_rowid disagrees with npk")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", INT8_TAIL)], &[]))
    );

    // Type bytes: unknown tags, unknown collation, array of array.
    assert_eq!(
        Err(RowError::Corrupt("unknown type tag")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x12, 0x00])], &[1]))
    );
    assert_eq!(
        Err(RowError::Corrupt("unknown type tag")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x00, 0x00])], &[1]))
    );
    assert_eq!(
        Err(RowError::Corrupt("unknown collation")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x08, 0x02, 0x00])], &[1]))
    );
    assert_eq!(
        Err(RowError::Corrupt("array of array type")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x11, 0x11, 0x01, 0x00])], &[1]))
    );
    // Gate follow-up f1 (M-1): the second 0x11 is rejected *before*
    // any recursion, so nesting depth cannot drive recursion. At 3
    // nested tags and at 100,000 the result is the same Err — the
    // deep one decoded on a small stack to prove no stack overflow.
    assert_eq!(
        Err(RowError::Corrupt("array of array type")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x11, 0x11, 0x11, 0x00])], &[1]))
    );
    let mut deep_tags = vec![0x11; 100_000];
    deep_tags.push(0x00); // the flags byte
    let deep = raw_def(1, 0, &[(1, "a", deep_tags.as_slice())], &[1]);
    let decode_deep = move || TableSchema::decode(&deep).map(|_| ());
    let small_stack = std::thread::Builder::new()
        .stack_size(256 * 1024)
        .spawn(decode_deep)
        .unwrap_or_else(|e| panic!("spawn: {e:?}"));
    assert_eq!(
        Err(RowError::Corrupt("array of array type")),
        small_stack
            .join()
            .unwrap_or_else(|e| panic!("decode thread panicked: {e:?}"))
    );
    // A truncated type (the text tag without its collation byte) is
    // covered by def_truncation_at_every_offset over the `text` case.

    // Attnums must be 1..=ncols in order.
    assert_eq!(
        Err(RowError::Corrupt("definition attnums out of order")),
        TableSchema::decode(&raw_def(
            1,
            0,
            &[(1, "a", INT8_TAIL), (3, "b", INT8_TAIL)],
            &[1]
        ))
    );
    assert_eq!(
        Err(RowError::Corrupt("definition attnums out of order")),
        TableSchema::decode(&raw_def(1, 0, &[(2, "a", INT8_TAIL)], &[1]))
    );

    // The pk must name live columns.
    assert_eq!(
        Err(RowError::Corrupt("primary key names a missing attnum")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", INT8_TAIL)], &[2]))
    );
    assert_eq!(
        Err(RowError::Corrupt("primary key names a missing attnum")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", INT8_TAIL)], &[0]))
    );
    assert_eq!(
        Err(RowError::Corrupt("primary key names a dropped attnum")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x04, 0x02])], &[1]))
    );

    // Unknown flag bits.
    assert_eq!(
        Err(RowError::Corrupt("unknown definition flags")),
        TableSchema::decode(&raw_def(1, 0, &[(1, "a", &[0x04, 0x08])], &[1]))
    );

    // A missing value that does not decode under the column type
    // (here: one byte for an int8).
    assert_eq!(
        Err(RowError::Corrupt("truncated value")),
        TableSchema::decode(&raw_def(
            1,
            0,
            &[(1, "a", &[0x04, 0x04, 0, 0, 0, 1, 0xFF])],
            &[1]
        ))
    );

    // A name that is not UTF-8.
    let mut bad_name = good.clone();
    bad_name[15] = 0xFF; // the single name byte of column "a"
    assert_eq!(
        Err(RowError::Corrupt("column name is not UTF-8")),
        TableSchema::decode(&bad_name)
    );

    // Trailing bytes.
    let mut trailing = good.clone();
    trailing.push(0x00);
    assert_eq!(
        Err(RowError::Corrupt("trailing bytes after definition")),
        TableSchema::decode(&trailing)
    );

    // Truncation of every offset of a multi-column def.
    let two_pk = raw_def(
        7,
        0,
        &[(1, "a", INT8_TAIL), (2, "b", &[0x08, 0x01, 0x01])],
        &[1, 2],
    );
    assert!(TableSchema::decode(&two_pk).is_ok());
    for cut in 0..two_pk.len() {
        assert!(
            TableSchema::decode(&two_pk[..cut]).is_err(),
            "accepted cut {cut} of {two_pk:02x?}"
        );
    }
}

/// `TableSchema::new` and `encode` refuse broken in-memory schemas with
/// `InvalidDdl` rather than writing broken bytes.
#[test]
fn new_and_encode_refusals() {
    let a = cd(1, "a", KeyType::Int4);
    let mut b = cd(2, "b", KeyType::Int4);

    // pk naming a missing or dropped attnum.
    assert_eq!(
        Err(RowError::InvalidDdl("primary key names a missing attnum")),
        TableSchema::new(vec![a.clone()], vec![2])
    );
    assert_eq!(
        Err(RowError::InvalidDdl("primary key names a missing attnum")),
        TableSchema::new(vec![a.clone()], vec![0])
    );
    b.dropped = true;
    assert_eq!(
        Err(RowError::InvalidDdl("primary key names a dropped attnum")),
        TableSchema::new(vec![a.clone(), b.clone()], vec![2])
    );

    // Attnums out of order.
    let mut disordered = cd(3, "c", KeyType::Int4);
    disordered.attnum = 4;
    assert_eq!(
        Err(RowError::InvalidDdl("attnums must be 1..=n in order")),
        TableSchema::new(vec![a.clone(), disordered], vec![1])
    );

    // hidden_rowid inconsistent with pk.
    let mut skewed = sch(vec![a.clone()], vec![1]);
    skewed.hidden_rowid = true;
    assert_eq!(
        Err(RowError::InvalidDdl(
            "hidden_rowid must equal pk.is_empty()"
        )),
        skewed.encode()
    );

    // An array-of-array column type.
    assert_eq!(
        Err(RowError::InvalidDdl("array of array type")),
        sch(
            vec![cd(
                1,
                "a",
                KeyType::Array(Box::new(KeyType::Array(Box::new(KeyType::Int4))))
            )],
            vec![1]
        )
        .encode()
    );
}

fn col_spec() -> BoxedStrategy<ColumnDef> {
    key_type()
        .prop_flat_map(|ty| {
            (
                optional_value(ty.clone()),
                any::<bool>(),
                any::<bool>(),
                vec(any::<char>(), 0..=6),
            )
                .prop_map(move |(missing, not_null, dropped, name)| {
                    // §3: DROP COLUMN clears not_null. `not_null_since`
                    // is normalized by `TableSchema::new` (the create
                    // version, 1) — the DDL helpers own every other
                    // value.
                    ColumnDef {
                        attnum: 0, // assigned 1..=n below
                        name: name.into_iter().collect(),
                        ty: ty.clone(),
                        not_null: not_null && !dropped,
                        not_null_since: 0,
                        dropped,
                        missing,
                    }
                })
        })
        .boxed()
}

// Random schemas round-trip through the def bytes, with any version,
// pk drawn from the live columns, and `hidden_rowid` derived.
proptest! {
    #![proptest_config(cfg())]

    #[test]
    fn def_round_trip(
        (version, specs, mask) in (1u32..=1000, vec(col_spec(), 0..=8)).prop_flat_map(|(v, specs)| {
            let n = specs.len();
            (Just(v), Just(specs), vec(any::<bool>(), n..=n))
        })
    ) {
        let columns: Vec<ColumnDef> = specs
            .into_iter()
            .enumerate()
            .map(|(i, mut c)| {
                c.attnum = i as u16 + 1;
                c
            })
            .collect();
        let live: Vec<u16> = columns
            .iter()
            .filter(|c| !c.dropped)
            .map(|c| c.attnum)
            .collect();
        let pk: Vec<u16> = live
            .iter()
            .zip(&mask)
            .filter(|(_, m)| **m)
            .map(|(a, _)| *a)
            .collect();
        let base =
            TableSchema::new(columns, pk.clone()).unwrap_or_else(|e| panic!("new: {e:?}"));
        let schema = TableSchema { version, ..base };
        prop_assert_eq!(schema.hidden_rowid, pk.is_empty());
        let bytes = schema.encode().unwrap_or_else(|e| panic!("encode: {e:?}"));
        let back = TableSchema::decode(&bytes).unwrap_or_else(|e| panic!("decode: {e:?}"));
        // Representation equality: a NaN `missing` is itself (C-Q3s
        // §8.1), `==` on Value is not.
        prop_assert!(schema_repr_eq(&schema, &back), "{schema:?} vs {back:?}");
    }
}

/// `==` on schemas modulo float NaN payloads in `missing` values.
fn schema_repr_eq(a: &TableSchema, b: &TableSchema) -> bool {
    a.version == b.version
        && a.hidden_rowid == b.hidden_rowid
        && a.pk == b.pk
        && a.columns.len() == b.columns.len()
        && a.columns.iter().zip(&b.columns).all(|(x, y)| {
            x.attnum == y.attnum
                && x.name == y.name
                && x.ty == y.ty
                && x.not_null == y.not_null
                && x.dropped == y.dropped
                && match (&x.missing, &y.missing) {
                    (None, None) => true,
                    (Some(p), Some(q)) => value_repr_eq(p, q),
                    _ => false,
                }
        })
}
